namespace sv_7b34d17e969e456b98fd72f39fc78a64.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Registered as Scoped so each Blazor Server circuit (i.e. each browser tab) gets
/// its own independent instance — one manager switching warehouses never affects another.
/// </summary>
public sealed class WarehouseStateService
{
    private string _currentWarehouseId = "WH-1";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-1", "Warehouse A — Main Distribution"),
        ("WH-2", "Warehouse B — East Regional"),
        ("WH-3", "Warehouse C — West Regional"),
        ("WH-4", "Warehouse D — Returns Processing"),
    ];

    /// <summary>
    /// Raised whenever the selected warehouse changes.
    /// Components subscribe in OnInitialized and unsubscribe in Dispose.
    /// </summary>
    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

namespace sv_7b34d17e969e456b98fd72f39fc78a64.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts for the active warehouse.
/// Polling is controlled by consumers (start/stop) and every new result is
/// broadcast to ALL subscribers so unrelated components stay in sync.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
    }

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Raised whenever a new alert count is available.
    /// Every subscribed component should call InvokeAsync(StateHasChanged) in the handler.
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency-free DB call; return random count 0–15.
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begins polling every 10 seconds. Safe to call multiple times —
    /// uses reference counting so the timer runs while at least one subscriber is active.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount > 1) return; // already running

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    /// <summary>
    /// Decrements the subscriber count. Stops polling when the last subscriber leaves.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            CancelPolling();
        }
    }

    /// <summary>
    /// Fetch a fresh count for the current warehouse and notify all subscribers.
    /// Useful for an immediate refresh (e.g. after a warehouse switch).
    /// </summary>
    public async Task RefreshAsync()
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start so the UI isn't blank for 10 s.
        await RefreshAsync();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose / stop.
        }
    }

    private void CancelPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        CancelPolling();
    }
}

