@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-nowrap" for="warehouseSelect">Warehouse:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="max-width: 300px;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in Services.WarehouseStateService.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "WH-1";
        // Immediately refresh alert count for the new warehouse.
        await AlertService.RefreshAsync();
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

