@page "/dashboard"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">
                    @(Services.WarehouseStateService.AvailableWarehouses
                        .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
                        ?? WarehouseState.CurrentWarehouseId)
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text fs-4">
                    @if (AlertService.CurrentAlertCount > 0)
                    {
                        <span class="text-danger fw-bold">
                            ⚠ @AlertService.CurrentAlertCount items below minimum
                        </span>
                    }
                    else
                    {
                        <span class="text-success fw-bold">
                            ✓ All items sufficiently stocked
                        </span>
                    }
                </p>
                <small class="text-muted">Polling every 10 seconds while this page is open</small>
            </div>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        // Subscribe to both change events so this page updates when:
        // 1. The warehouse selector in the layout changes the active warehouse.
        // 2. The polling timer fetches a new alert count.
        WarehouseState.OnChange += OnStateChanged;
        AlertService.OnAlertCountChanged += OnStateChanged;

        // Start the 10-second polling loop. Reference-counted, so multiple
        // subscribers won't create duplicate timers.
        AlertService.StartPolling();
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
        AlertService.OnAlertCountChanged -= OnStateChanged;

        // Stop polling when the user navigates away from the dashboard.
        AlertService.StopPolling();
    }
}

